import org.xml.sax.SAXException;

import java.io.IOException;
import java.io.StringReader;

/**
 * Service class for validating XML configuration requests.
 */
public class ConfigLoaderService {

    /**
     * Validates whether the provided XML content is well-formed.
     *
     * @param xmlContent The XML string to be validated; must not be null or empty.
     * @return true if the XML content is well-formed, false otherwise.
     */
    public boolean load(String xmlContent) {
        if (xmlContent == null || xmlContent.trim().isEmpty()) {
            return false;
        }

        Digester digester = new Digester();
        // Disable DTD processing completely to prevent XXE and entity expansion attacks.
        try {
            digester.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (Exception ignored) {
            // Feature not supported
        }
        // Explicitly disable external entities (security hardening)
        try {
            digester.setFeature("http://xml.org/sax/features/external-general-entities", false);
            digester.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        } catch (Exception ignored) {
            // Feature not supported
        }
        digester.setValidating(false);

        // Parse the XML content; any well‑formedness error will cause an exception.
        try (StringReader reader = new StringReader(xmlContent)) {
            digester.parse(reader);
            return true;
        } catch (IOException | SAXException e) {
            return false;
        }
    }
}

